import 'package:meta/meta.dart';

import 'inputs_outputs.dart';
import 'options.dart';
import 'planning.dart';
import 'types.dart';

/// Builds libvips CLI argument lists (spec 03 §3.2). Pure; no I/O.
///
/// File names passed in must be generated by the library (no `[`, `,` or
/// other libvips option syntax), because libvips parses `name[options]`.
/// Exposed (internally) for unit tests that assert exact command lines.
@internal
abstract final class CliArgs {
  /// Width passed to `thumbnail` for height-only fits (the libvips idiom).
  static const unconstrained = 10000000;

  /// Loader options appended to the source file name.
  static String loadOptions(ImageFormat format, {required bool allFrames}) =>
      switch (format) {
        ImageFormat.gif || ImageFormat.webp => '[n=${allFrames ? -1 : 1}]',
        _ => '',
      };

  /// Saver options appended to the output file name.
  static String saveOptions(
    Encode encode,
    MetadataPolicy metadata, {
    int? pageHeight,
  }) {
    final options = <String>[
      ...switch (encode) {
        final WebpEncode e => [
          'Q=${e.quality}',
          'lossless=${e.lossless}',
          'effort=${e.effort}',
          'smart_subsample=${e.smartSubsample}',
          'alpha_q=${e.alphaQuality}',
        ],
        final JpegEncode e => [
          'Q=${e.quality}',
          'interlace=${e.progressive}',
          'optimize_coding=${e.optimizeCoding}',
          'subsample_mode=${switch (e.subsampling) {
            ChromaSubsampling.auto => 'auto',
            ChromaSubsampling.yuv420 => 'on',
            ChromaSubsampling.yuv444 => 'off',
          }}',
          // JPEG has no alpha: flatten onto white rather than black.
          'background=255',
        ],
        final PngEncode e => [
          'compression=${e.compression}',
          if (e.palette) ...['palette=true', 'bitdepth=${_bitDepth(e.colors)}'],
        ],
        _ => throw ArgumentError.value(encode, 'encode', 'Unsupported encoder'),
      },
      'keep=${metadata.name}',
      if (pageHeight != null) 'page_height=$pageHeight',
    ];
    return '[${options.join(',')}]';
  }

  static int _bitDepth(int colors) => colors <= 2
      ? 1
      : colors <= 4
      ? 2
      : colors <= 16
      ? 4
      : 8;

  /// `vips thumbnail` arguments.
  static List<String> thumbnail({
    required String source,
    required String loadOptions,
    required String output,
    required int width,
    int? height,
    String size = 'down',
    String? crop,
    required TransformOptions options,
  }) => [
    'thumbnail',
    '$source$loadOptions',
    output,
    '$width',
    if (height != null) ...['--height', '$height'],
    '--size',
    size,
    if (crop != null) ...['--crop', crop],
    if (!options.autoOrient) '--no-rotate',
    if (options.color == ColorPolicy.srgb) ...['--export-profile', 'srgb'],
    '--fail-on',
    options.failOn.name,
  ];

  /// `vips extract_area` arguments.
  static List<String> extractArea(
    String source,
    String output,
    int left,
    int top,
    int width,
    int height,
  ) => ['extract_area', source, output, '$left', '$top', '$width', '$height'];

  /// The `vips thumbnail` step for [planned]: either the final render
  /// (fit, no resize, libvips crops on stills) or the resize step of a
  /// two-step crop, written to [intermediate].
  static List<String> renderStep(
    PlannedOutput planned,
    ImageInfo source, {
    required String sourcePath,
    required String output,
    required String intermediate,
    required TransformOptions options,
    required bool needsManualCrop,
  }) {
    final load = loadOptions(source.format, allFrames: planned.loadAllFrames);
    final save = saveOptions(planned.output.encode, options.metadata);
    final resize = planned.output.resize;
    final fit = planned.fit;
    final cover = planned.cover;
    if (cover != null && resize is CoverResize) {
      if (needsManualCrop) {
        return thumbnail(
          source: sourcePath,
          loadOptions: load,
          output: intermediate,
          width: cover.resizedWidth,
          height: cover.resizedHeight,
          size: 'force',
          options: options,
        );
      }
      return thumbnail(
        source: sourcePath,
        loadOptions: load,
        output: '$output$save',
        width: cover.boxWidth,
        height: cover.boxHeight,
        size: resize.upscale ? 'both' : 'down',
        crop: switch (resize.crop) {
          AttentionCrop() => 'attention',
          EntropyCrop() => 'entropy',
          _ => 'centre',
        },
        options: options,
      );
    }
    if (fit != null && resize is FitResize) {
      return thumbnail(
        source: sourcePath,
        loadOptions: load,
        output: '$output$save',
        width: resize.width ?? unconstrained,
        // `thumbnail` defaults the height to the width, so a width-only fit
        // needs an explicit unconstrained height.
        height: resize.height ?? unconstrained,
        size: resize.upscale ? 'both' : 'down',
        options: options,
      );
    }
    // No resize: re-encode at the (oriented) source size.
    return thumbnail(
      source: sourcePath,
      loadOptions: load,
      output: '$output$save',
      width: planned.plan.width,
      height: planned.plan.height,
      options: options,
    );
  }
}
